if(typeof require==='function'){var Constants=require('./constants');var Upgrade=require('./upgrade');}var SpeedBoostUpgrade=Upgrade.subclass();SpeedBoostUpgrade.fields({_lifetime:0,_speedBoost:0});SpeedBoostUpgrade.classMethods({createInitialUpgradeState:function(id,playerId,lifetime,speedBoost){var fields={_lifetime:lifetime,_speedBoost:speedBoost};return Upgrade.createInitialUpgradeState(id,playerId,Constants.UPGRADE_TYPES.SPEED_BOOST,JSON.stringify(fields));}});SpeedBoostUpgrade.methods({update:function(deltaTime){this._lifetime-=deltaTime;},done:function(){return this._lifetime<=0;}});if(typeof module==='object'){module.exports=SpeedBoostUpgrade;}